const e=[{id:"mechanical",name:"Design & Manufacturing",shortName:"Mechanical",color:"#e07a3a",icon:"gear",poi:"mechanical-workshop",summary:"Every part of DAWN starts as a sketch, becomes a CAD model, and ends as machined aluminium. This crew owns the chassis, the rocker-bogie suspension, the arm structure, and the fabrication that turns designs into hardware.",responsibilities:["Chassis and rocker-bogie suspension design","Robotic arm mechanical structure","CNC machining, 3D printing, sheet-metal fabrication","Weight, tolerance and structural analysis"]},{id:"electrical",name:"Electrical & Power",shortName:"Electrical",color:"#f5c96b",icon:"bolt",poi:"electrical-lab",summary:"Power budgets, wiring harnesses, motor drivers, sensor buses. This team keeps every joule accounted for and every signal clean, from the solar-analogue battery pack to the last servo.",responsibilities:["Power distribution and battery management","Motor drivers and actuator electronics","Sensor integration and signal conditioning","PCB design and harness manufacturing"]},{id:"controls",name:"Controls & Embedded",shortName:"Controls",color:"#7fd0d4",icon:"cpu",poi:"software-center",summary:"Real-time firmware, teleoperation, arm inverse kinematics, drive control. If the rover moves, this team wrote the code that told it how.",responsibilities:["Embedded firmware and real-time control loops","Teleoperation link and ground station software","Robotic arm inverse kinematics","Drive-by-wire and skid-steer control"]},{id:"autonomy",name:"AI & Autonomy",shortName:"AI",color:"#c084ff",icon:"brain",poi:"robotics-lab",summary:"Perception, mapping, and decision-making. This is where DAWN learns to see the Martian analogue, plan a path across it, and reach a waypoint without a human in the loop.",responsibilities:["SLAM, mapping and localisation","Computer vision for object and Aruco marker detection","Autonomous navigation and path planning","Machine-learning-based perception"]},{id:"science",name:"Science",shortName:"Science",color:"#8adb8a",icon:"flask",poi:"science-lab",summary:"The reason the rover exists. This team designs the sample-collection payload, life-detection assays, and the science plan the URC/IRC judges score us on.",responsibilities:["Onboard science payload design","Sample acquisition and containment","Life-detection and geology protocols","Science report authoring"]},{id:"documentation",name:"Research & Documentation",shortName:"Research",color:"#a3b3c2",icon:"book",poi:"mission-control",summary:"SDDR clearance, whitepapers, judge briefings, media assets. Every technical decision is documented so the next season starts ahead of this one.",responsibilities:["System Design & Documentation Reviews (SDDR)","Technical whitepapers and competition submissions","Knowledge base and continuity between seasons","Media, brochure, and sponsor collateral"]}],a={departments:e};export{a as default,e as departments};
